                    cur_min1 = b
                elif b < cur_min2:
                    cur_min2 = b
            min1[x] = cur_min1
            min2[x] = cur_min2

        base_total = 0
        for x in range(1, n+1):
            base_total += min1[x] - x

        groups = defaultdict(list)
        for x in range(1, n+1):
            b_val = min1[x]
            if b_val <= n:
                diff = min2[x] - min1[x]
                groups[b_val].append((x, diff))

        group_data = {}
        for b, lst in groups.items():
            lst.sort(key=lambda t: t[0])
            xs = [item[0] for item in lst]
            ps = [0]
            for i in range(len(lst)):
                ps.append(ps[-1] + lst[i][1])
            group_data[b] = (xs, ps)

        best = 0
        for a0, b0 in conflictingPairs:
            delta = 0
            if b0 in group_data:
                xs, ps = group_data[b0]
                idx = bisect.bisect_right(xs, a0)
                delta = ps[idx]
            total_valid = base_total + delta
            if total_valid > best:
                best = total_valid

        return best

