        current_count_max1 = 0
        current_max2 = 0

        for r in range(1, n + 1):
            for a_val in by_b[r]:
                if a_val > current_max1:
                    current_max2 = current_max1
                    current_max1 = a_val
                    current_count_max1 = 1
                elif a_val == current_max1:
                    current_count_max1 += 1
                elif a_val > current_max2:
                    current_max2 = a_val

            max1_arr[r] = current_max1
            count_max1_arr[r] = current_count_max1
            max2_arr[r] = current_max2

        base_total = 0
        for r in range(1, n + 1):
            base_total += (r - max1_arr[r])

        groups = defaultdict(list)
        for r in range(1, n + 1):
            if count_max1_arr[r] == 1:
                a_val = max1_arr[r]
                groups[a_val].append(r)

        prefix_sums = {}
        for a_val, r_list in groups.items():
            r_list.sort()
            ps = [0]
            for r_pos in r_list:
                ps.append(ps[-1] + max2_arr[r_pos])
            prefix_sums[a_val] = ps

        best = base_total
        for a0, b0 in normalized:
            if a0 not in groups:
                continue
            r_list = groups[a0]
            idx = bisect.bisect_left(r_list, b0)
            if idx < len(r_list):
                count = len(r_list) - idx
                ps = prefix_sums[a0]
                total_max2 = ps[-1] - ps[idx]
                increase = a0 * count - total_max2
                candidate = base_total + increase
                if candidate > best:
                    best = candidate

        return best

