class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        total_subarrays = n * (n + 1) // 2

        min_b_for_a = [float('inf')] * (n + 1)
        normalized_pairs = []
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            normalized_pairs.append((a, b, idx))
            if b < min_b_for_a[a]:
                min_b_for_a[a] = b

        next_invalid = [float('inf')] * (n + 2)
        next_invalid[n + 1] = float('inf')
        for L in range(n, 0, -1):
            next_invalid[L] = min(min_b_for_a[L], next_invalid[L + 1])

        V_count = 0
        for L in range(1, n + 1):
            r_max = min(next_invalid[L] - 1, n)
            if r_max >= L:
                V_count += (r_max - L + 1)

        base = V_count

        events = [[] for _ in range(n + 1)]
        for (a, b, idx) in normalized_pairs:
            events[b].append((a, idx))

        X = [0] * (n + 1)
        Y = [0] * (n + 1)
        Z = [-1] * (n + 1)

        best1_val = 0
        best1_idx = -1
        best2_val = 0
        best2_idx = -1

        for R in range(1, n + 1):
            for (c, idx) in events[R]:
                if c > best1_val:
                    best2_val, best2_idx = best1_val, best1_idx
                    best1_val, best1_idx = c, idx
                elif c > best2_val:
                    best2_val, best2_idx = c, idx
            X[R] = best1_val
            Y[R] = best2_val
            Z[R] = best1_idx

        P_X = [0] * (n + 1)
        P_Y = [0] * (n + 1)
        for R in range(1, n + 1):
            P_X[R] = P_X[R - 1] + X[R]
            P_Y[R] = P_Y[R - 1] + Y[R]

        min_d_exact = [float('inf')] * (n + 1)
        for (a, b, idx) in normalized_pairs:
            if b < min_d_exact[a]:
                min_d_exact[a] = b

        suff_min = [float('inf')] * (n + 2)
        suff_min[n + 1] = float('inf')
        for c in range(n, 0, -1):
            suff_min[c] = min(min_d_exact[c], suff_min[c + 1])

        max_h = 0

        for (a, b, idx) in normalized_pairs:
            best1_before = X[b - 1] if b > 1 else 0
            if a <= best1_before:
                h_j = 0
            else:
                R_switch = suff_min[a + 1]
                if R_switch == float('inf'):
                    R_switch = n + 1
                L_j = b
                R_j = min(R_switch - 1, n)

                lo, hi = 1, n
                T1 = 0
                while lo <= hi:
                    mid = (lo + hi) // 2
                    if X[mid] < a:
                        T1 = mid
                        lo = mid + 1
                    else:
                        hi = mid - 1

                r1 = min(T1, n)
                if r1 < b:
                    S1 = 0
                else:
                    S1 = (r1 - b + 1) * a - (P_X[r1] - P_X[b - 1])

                l2 = max(b, L_j)
                r2 = min(n, R_j)
                if l2 > r2:
                    S2 = 0
                else:
                    T2 = min(r2, T1)
                    if T2 < l2:
                        S2 = 0
                    else:
                        S2 = (T2 - l2 + 1) * a - (P_X[T2] - P_X[l2 - 1])

                lo, hi = 1, n
                T3 = 0
                while lo <= hi:
                    mid = (lo + hi) // 2
                    if Y[mid] < a:
                        T3 = mid
                        lo = mid + 1
                    else:
                        hi = mid - 1

                l3 = l2
                r3 = r2
                if l3 > r3:
                    S3 = 0
                else:
                    T3_local = min(r3, T3)
                    if T3_local < l3:
                        S3 = 0
                    else:
                        S3 = (T3_local - l3 + 1) * a - (P_Y[T3_local] - P_Y[l3 - 1])

                h_j = S1 - S2 + S3

            if h_j > max_h:
                max_h = h_j

        return base + max_h

