class Solution:
    def maxFreeTime(self, eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
        n = len(startTime)

        pref = [0] * (n + 1)
        for i in range(n):
            dur = endTime[i] - startTime[i]
            pref[i + 1] = pref[i] + dur

        Lbound = [0] * n
        for i in range(n):
            if i == 0:
                Lbound[i] = 0
            else:
                Lbound[i] = endTime[i - 1]

        Rbound = [0] * (n + 1)
        for i in range(n + 1):
            if i < n:
                Rbound[i] = startTime[i]
            else:
                Rbound[i] = eventTime

        C = [0] * (n + 1)
        for i in range(n + 1):
            C[i] = Rbound[i] - pref[i]

        D = [0] * n
        for i in range(n):
            D[i] = Lbound[i] - pref[i]

        M = [0] * n
        deq = deque()

        end0 = min(k, n)
        for idx in range(1, end0 + 1):
            while deq and C[deq[-1]] <= C[idx]:
                deq.pop()
            deq.append(idx)
        M[0] = C[deq[0]] if deq else -10**18

        for i in range(1, n):
            R_prev = min((i - 1) + k, n)
            R_new = min(i + k, n)

            if R_new > R_prev:
                idx = R_new
                while deq and C[deq[-1]] <= C[idx]:
                    deq.pop()
                deq.append(idx)

            while deq and deq[0] < i + 1:
                deq.popleft()

            M[i] = C[deq[0]] if deq else -10**18

        orig_max = 0
        prev_end = 0
        for i in range(n):
            gap = startTime[i] - prev_end
            if gap > orig_max:
                orig_max = gap
            prev_end = endTime[i]
        gap = eventTime - prev_end
        if gap > orig_max:
            orig_max = gap

        best_move = -10**18
        for i in range(n):
            val = M[i] - D[i]
            if val > best_move:
                best_move = val

        return max(orig_max, best_move)

class Solution:
    def maxFreeTime(self, eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
        n = len(startTime)
        m = n + 1
        gaps = [0] * m
        gaps[0] = startTime[0]
        for i in range(1, n):
            gaps[i] = startTime[i] - endTime[i-1]
        gaps[n] = eventTime - endTime[n-1]

        prefix = [0] * (m + 1)
        for i in range(m):
            prefix[i+1] = prefix[i] + gaps[i]

        P = m - k
        ans = 0

        for l in range(m):
            candidate_r = -1
            L = l
            R_full = m - 1 - (m - 1)
            min_left_full = 1 if L > 0 else 0
            min_right_full = 1 if R_full > 0 else 0
            a_min_full = max(min_left_full, P - 1 - R_full)
            a_max_full = min(L, P - 1 - min_right_full)
            if a_min_full <= a_max_full:
                candidate_r = m - 1
            else:
                min_left = 1 if l > 0 else 0
                c2 = min(l, P - 2)
                if min_left <= c2:
                    r_candidate = min(m - 2, c2 + k)
                    if r_candidate >= l:
                        candidate_r = r_candidate
                    else:
                        candidate_r = -1
                else:
                    candidate_r = -1

            if candidate_r != -1:
                total = prefix[candidate_r + 1] - prefix[l]
                if total > ans:
                    ans = total

        return ans

