class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        # Group by diagonal difference d = j - i
        diagonals = {}

        for i in range(n):
            for j in range(n):
                d = j - i
                if d not in diagonals:
                    diagonals[d] = []
                diagonals[d].append((i, j))

        # Process each diagonal
        for d, positions in diagonals.items():
            # Extract values in order along the diagonal
            values = [grid[i][j] for i, j in positions]

            # Sort based on which triangle
            if d <= 0:
                # Bottom-left triangle: non-increasing
                values.sort(reverse=True)
            else:
                # Top-right triangle: non-decreasing
                values.sort()

            # Put sorted values back
            for k, (i, j) in enumerate(positions):
                grid[i][j] = values[k]

        return grid

